// dcom_client.cpp

#include "dcom_client.h"

DCOMClient::DCOMClient() : m_pUnk(nullptr) {}

DCOMClient::~DCOMClient() {
    if (m_pUnk != nullptr) {
        m_pUnk->Release();
    }
}

HRESULT DCOMClient::ConnectToServer(const wchar_t* serverName, const wchar_t* serviceName) {
    // 连接到远程服务器
    HRESULT hr = CoInitializeSecurity(NULL, -1, NULL, NULL, RPC_C_AUTHN_LEVEL_DEFAULT, RPC_C_IMP_LEVEL_IMPERSONATE, NULL, EPT_AUTHENTICATION_REQUIRED, 0, NULL);
    if (FAILED(hr)) {
        return hr;
    }

    hr = CoCreateInstance(CLSID_DCMClientFactory, NULL, CLSCTX_LOCAL_SERVER | CLSCTX_REMOTE_SERVER, IID_IDispatch, reinterpret_cast<void**>(&m_pUnk));
    if (FAILED(hr)) {
        CoUninitialize();
        return hr;
    }

    // 连接到服务
    hr = m_pUnk->Connect(serverName, serviceName);
    if (FAILED(hr)) {
        m_pUnk->Release();
        m_pUnk = nullptr;
    }

    return hr;
}

HRESULT DCOMClient::RegisterService(const wchar_t* serviceInterface) {
    // 注册服务
    HRESULT hr = m_pUnk->Register(serviceInterface);
    if (FAILED(hr)) {
        return hr;
    }

    return S_OK;
}

HRESULT DCOMClient::ExecuteService(const wchar_t* method, void* params) {
    // 执行服务方法
    HRESULT hr = m_pUnk->Invoke(method, params);
    if (FAILED(hr)) {
        return hr;
    }

    return S_OK;
}
