int main()
{
    // 创建ETW会话
    HANDLE hSession;
    if (OpenSession(&hSession) != ERROR_SUCCESS)
    {
        printf("Failed to open ETW session\n");
        return -1;
    }

    // 禁用事件追踪
    CONTROL_EVENT controlEvent = {};
    controlEvent.EventNameGuid = g_DisableSecurityEvent;
    controlEvent.EnableFlags = 0x00000000; // 关闭事件追踪
    if (ControlEvent(hSession, EVENT_CONTROL_ENABLE_GUIDS, &controlEvent) != ERROR_SUCCESS)
    {
        printf("Failed to disable event tracing\n");
        return -1;
    }

    // 关闭ETW会话
    CloseHandle(hSession);

    return 0;
}
```
